            } catch (e: Exception) {
                if (e is CancellationException) throw e
                if (seq != futureSeq.get() || reqUid != activeUserId || reqGen != SessionCacheManager.currentGeneration()) {
                    return@launch
                }
                _uiState.update {
                    it.copy(
                        isFutureLoadingMore = false,
                        error = friendlyBusinessPolicyError(e, localizer),
                    )
                }
            }
        }
