                    return@launch
                }
                _uiState.update { state ->
                    state.copy(
                        isHistoryLoadingMore = false,
                        historyItems = state.historyItems + envelope.items,
                        historyHasMore = envelope.hasMore,
                        historyNextCursor = envelope.nextCursor,
                    )
                }
            } catch (e: Exception) {
                if (e is CancellationException) throw e
                if (seq != historySeq.get() || reqUid != activeUserId || reqGen != SessionCacheManager.currentGeneration()) {
                    return@launch
                }
                _uiState.update {
                    it.copy(
                        isHistoryLoadingMore = false,
                        error = friendlyBusinessPolicyError(e, localizer),
                    )
                }
            }
        }
    }

    fun clearError() {
        _uiState.update { it.copy(error = null) }
    }

    fun clearSuccess() {
        _uiState.update { it.copy(successMessage = null) }
    }
